import { test, expect } from '@playwright/test';

test.describe('External Links Open in New Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page-with-external-links');
  });

  test('should open external links in a new tab', async ({ page }) => {
    // Verify the page is loaded
    await expect(page.getByRole('heading', { name: /page content/i })).toBeVisible();

    // Get the external link button using getByRole
    const externalLinkButton = page.getByRole('button', { name: /visit external site/i });
    await expect(externalLinkButton).toBeVisible();

    // Intercept the navigation to verify it opens in a new tab
    await page.waitForEvent('navigation');

    // Click the external link button
    await externalLinkButton.click();

    // Verify the new tab is open
    const newTab = page.context().pages().find((p) => p.url().includes('external-site.com'));
    expect(newTab).toBeDefined();

    // Verify the original page is still open
    const originalPage = page.context().pages().find((p) => p.url().includes('/page-with-external-links'));
    expect(originalPage).toBeDefined();

    // Verify the original page content is still visible
    await expect(page.getByRole('heading', { name: /page content/i })).toBeVisible();

    // Verify the external link content is visible in the new tab
    await expect(newTab.getByRole('heading', { name: /external site title/i })).toBeVisible();
  });

  test('should handle multiple external links and close new tab when navigating back', async ({ page }) => {
    // Verify the page is loaded
    await expect(page.getByRole('heading', { name: /page content/i })).toBeVisible();

    // Get the first external link button using getByRole
    const firstExternalLinkButton = page.getByRole('button', { name: /visit external site/i });
    await expect(firstExternalLinkButton).toBeVisible();

    // Click the first external link button
    await firstExternalLinkButton.click();

    // Verify the first new tab is open
    const firstNewTab = page.context().pages().find((p) => p.url().includes('external-site.com'));
    expect(firstNewTab).toBeDefined();

    // Get the second external link button using getByRole
    const secondExternalLinkButton = page.getByRole('button', { name: /visit another external site/i });
    await expect(secondExternalLinkButton).toBeVisible();

    // Click the second external link button
    await secondExternalLinkButton.click();

    // Verify the second new tab is open
    const secondNewTab = page.context().pages().find((p) => p.url().includes('another-external-site.com'));
    expect(secondNewTab).toBeDefined();

    // Verify both new tabs are open
    const allNewTabs = page.context().pages().filter((p) => p.url().includes('external-site.com') || p.url().includes('another-external-site.com'));
    expect(allNewTabs.length).toBe(2);

    // Navigate back to the original page
    await page.goBack();

    // Verify the original page is still visible
    await expect(page.getByRole('heading', { name: /page content/i })).toBeVisible();

    // Verify the original page URL is correct
    await expect(page).toHaveURL(/.*page-with-external-links/);
  });
});
